<?php
namespace App\Models;
use App\Models\Concerns\InvalidatesArticles; use Illuminate\Database\Eloquent\{Builder,Factories\HasFactory,Model}; use Illuminate\Database\Eloquent\Relations\{BelongsTo,BelongsToMany,HasMany};
class Article extends Model { use HasFactory,InvalidatesArticles; protected $fillable=['article_category_id','title','slug','eyebrow','excerpt','body','featured_image_path','featured_image_alt','author_name','reading_time_minutes','status','is_featured','display_order','published_at','scheduled_for','archived_at','meta_title','meta_description','canonical_url','og_title','og_description','og_image_path','robots_index','robots_follow','created_by','updated_by']; protected function casts():array{return ['is_featured'=>'boolean','robots_index'=>'boolean','robots_follow'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];} public function category():BelongsTo{return $this->belongsTo(ArticleCategory::class,'article_category_id');} public function homepageItems():HasMany{return $this->hasMany(HomepageItem::class);} public function relatedArticles():BelongsToMany{return $this->belongsToMany(self::class,'article_article_relations','article_id','related_article_id')->withPivot('display_order')->orderByPivot('display_order');} public function relatedSolutions():BelongsToMany{return $this->belongsToMany(Solution::class,'article_solution_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedProducts():BelongsToMany{return $this->belongsToMany(Product::class,'article_product_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedIndustries():BelongsToMany{return $this->belongsToMany(Industry::class,'article_industry_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedCapabilities():BelongsToMany{return $this->belongsToMany(Capability::class,'article_capability_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedPages():BelongsToMany{return $this->belongsToMany(Page::class,'article_page_relations')->withPivot('display_order')->orderByPivot('display_order');} public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));} public function isPubliclyVisible():bool{return $this->archived_at===null&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}
